export function getPhrases(code: LanguageCode): BookingPhrases {
  return BOOKING_PHRASES[code] || BOOKING_PHRASES.en;
}

/**
 * Carries the rider's chosen language down to the nested booking components
 * (bike identity, symptom checklist, express SOS) so the entire form — not just
 * the top-level labels — renders in one language.
 */
export interface BookingLanguageValue {
  language: LanguageCode;
  t: BookingPhrases;
  rtl: boolean;
  setLanguage: (code: LanguageCode) => void;
}

const BookingLanguageContext = createContext<BookingLanguageValue | null>(null);

export const BookingLanguageProvider: React.FC<{
  value: BookingLanguageValue;
  children: React.ReactNode;
}> = ({ value, children }) =>
  React.createElement(BookingLanguageContext.Provider, { value }, children);

const ENGLISH_FALLBACK: BookingLanguageValue = {
  language: 'en',
  t: BOOKING_PHRASES.en,
  rtl: false,
  setLanguage: () => {},
};

/** The phrases for the surrounding booking form (English when used standalone). */
export function useBookingPhrases(): BookingPhrases {
  return (useContext(BookingLanguageContext) ?? ENGLISH_FALLBACK).t;
}

/** The full language state for the surrounding booking form. */
export function useBookingLanguage(): BookingLanguageValue {
  return useContext(BookingLanguageContext) ?? ENGLISH_FALLBACK;
}

/** English name of a language code (e.g. 'pl' → 'Polish'), for staff labels. */
export function languageEnglishName(code: string): string {
  return BOOKING_LANGUAGES.find((l) => l.code === code)?.english || code;
}
